<script>
function syncQuestionForm(form){const type=form.querySelector('.question-type').value;form.querySelector('.option-settings')?.classList.toggle('d-none',!['dropdown','radio','checkbox'].includes(type));form.querySelector('.file-settings')?.classList.toggle('d-none',!['file','photo'].includes(type));}
document.querySelectorAll('.question-form').forEach(form=>{syncQuestionForm(form);form.querySelector('.question-type').addEventListener('change',()=>syncQuestionForm(form));form.querySelector('.option-source')?.addEventListener('change',e=>form.querySelector('.options-text').classList.toggle('d-none',e.target.value==='users'));});

document.getElementById('copyLink')?.addEventListener('click',async function(){
    const original=this.innerHTML;
    try{
        if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(this.dataset.url);}else{const field=document.createElement('textarea');field.value=this.dataset.url;document.body.appendChild(field);field.select();document.execCommand('copy');field.remove();}
        this.innerHTML='<i class="bx bx-check me-1"></i>Link Tersalin';this.classList.replace('btn-primary','btn-success');
        setTimeout(()=>{this.innerHTML=original;this.classList.replace('btn-success','btn-primary');},2200);
    }catch(error){this.innerHTML='<i class="bx bx-error me-1"></i>Gagal Menyalin';this.classList.replace('btn-primary','btn-danger');}
});

(function(){
    const list=document.getElementById('questionList');
    const status=document.getElementById('sortStatus');
    if(!list||list.querySelectorAll('.question-item').length<2)return;
    let dragged=null,handle=null,changed=false;
    const renumber=()=>list.querySelectorAll('.question-item').forEach((item,index)=>{const number=item.querySelector('.question-number');if(number)number.textContent=index+1;});
    const setStatus=(text,state='')=>{status.textContent=text;status.className='sort-status'+(state?' is-'+state:'');};
    const finish=async()=>{
        if(!dragged)return;
        dragged.classList.remove('is-dragging');list.classList.remove('is-sorting');
        try{handle?.releasePointerCapture?.(handle.pointerId);}catch(error){}
        dragged=null;handle=null;
        if(!changed)return;
        changed=false;setStatus('Menyimpan...','saving');
        try{
            const response=await fetch(list.dataset.reorderUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({question_ids:[...list.querySelectorAll('.question-item')].map(item=>Number(item.dataset.questionId))})});
            if(!response.ok)throw new Error('Gagal menyimpan urutan');
            setStatus('Urutan tersimpan','success');setTimeout(()=>setStatus(''),2500);
        }catch(error){setStatus('Gagal disimpan','error');}
    };
    list.querySelectorAll('.drag-handle').forEach(grip=>grip.addEventListener('pointerdown',event=>{
        if(event.button!==undefined&&event.button!==0)return;
        event.preventDefault();dragged=grip.closest('.question-item');handle=grip;changed=false;
        grip.pointerId=event.pointerId;grip.setPointerCapture?.(event.pointerId);dragged.classList.add('is-dragging');list.classList.add('is-sorting');setStatus('Geser lalu lepaskan','saving');
    }));
    document.addEventListener('pointermove',event=>{
        if(!dragged)return;event.preventDefault();
        const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('.question-item');
        if(!target||target===dragged||target.parentElement!==list)return;
        const rect=target.getBoundingClientRect();
        list.insertBefore(dragged,event.clientY<rect.top+rect.height/2?target:target.nextSibling);changed=true;renumber();
    },{passive:false});
    document.addEventListener('pointerup',finish);document.addEventListener('pointercancel',finish);
})();
</script>
